// Included within Window. Opens a separate example only after maybeSave succeeds.
 void loadTeachingExample(bool shop){
  if(!maybeSave())return;
  auto example=shop?shopExample():purchaseExample();QString error;Model verified;
  if(!Model::parse(QJsonDocument(example.json()).toJson(),verified,error)){QMessageBox::warning(this,t("Esempio","Example"),localizedError(error,en));return;}
  installExample(example,true);
 }
 void shopGuide(){
  QDialog dialog(this);dialog.setWindowTitle(t("Negozio — panoramica","Shop — overview"));QVBoxLayout layout(&dialog);QTextBrowser text;layout.addWidget(&text);
  text.setHtml(colorHelpHtml(t("<h3>Leggere l’esempio Negozio</h3><p>Un negozio vende prodotti a clienti privati e aziende. I clienti effettuano ordini, composti da righe; ogni riga riguarda un prodotto. I prodotti sono organizzati in categorie, che possono comprendere altre categorie.</p><h3>Che cosa osservare nel concettuale</h3><p>Privato e Azienda sono sottoclassi di Cliente: ne ereditano gli attributi e l’identificatore. CodiceFiscale e PartitaIVA offrono altri modi per riconoscere i clienti. RigaOrdine, invece, è un’entità debole: il suo numero distingue una riga soltanto all’interno dello stesso ordine.</p><p>Confronta i collegamenti: un ordine può avere una sola fattura, mentre un prodotto può appartenere a più categorie. L’associazione Comprende collega Categoria a se stessa, nei ruoli di categoria superiore e sottocategoria.</p><h3>Seguire il passaggio alle tabelle</h3><p>Nel logico, Privato e Azienda hanno ciascuna una tabella collegata a Cliente. La chiave di RigaOrdine comprende il numero della riga e il riferimento all’ordine. La classificazione dei prodotti richiede una tabella con gli abbinamenti fra prodotti e categorie.</p><p>La tabella Fattura contiene il riferimento all’ordine. Il vincolo UNIQUE impedisce che due fatture si riferiscano allo stesso ordine. Una colonna di Categoria rimanda invece alla stessa tabella, per indicare la categoria superiore.</p><h3>Provare una modifica</h3><p>Cambia un attributo nel concettuale, premi Genera/Aggiorna logico e leggi le modifiche proposte. Poi premi F8 per generare il nuovo SQL. L’esempio è configurato per HSQLDB; puoi scegliere anche MySQL o MariaDB. PrezzoUnitario usa Valuta, mentre PesoKg è un numero approssimato.</p><h3>Le regole da verificare</h3><p>Le tabelle e le chiavi non bastano a verificare tutte le regole. Occorre controllare che gli ordini abbiano le righe richieste e che una categoria non contenga, direttamente o indirettamente, se stessa. Se ogni cliente deve essere soltanto privato oppure azienda, anche questa regola richiede un controllo.</p>","<h3>Reading the Shop example</h3><p>A shop sells products to private customers and companies. Customers place orders made up of lines; each line refers to a product. Products belong to categories, which can include other categories.</p><h3>What to look for in the conceptual model</h3><p>Privato and Azienda are subclasses of Cliente: they inherit its attributes and identifier. CodiceFiscale and PartitaIVA provide other ways to identify customers. RigaOrdine is a weak entity: its number distinguishes a line only within the same order.</p><p>Compare the relationships: an order can have one invoice, while a product can belong to several categories. Comprende connects Categoria to itself in the roles of parent category and subcategory.</p><h3>Following the move to tables</h3><p>In the logical model, Privato and Azienda each have a table linked to Cliente. The key of RigaOrdine includes its line number and a reference to the order. Product classification needs a table holding pairs of products and categories.</p><p>Fattura contains a reference to the order. A UNIQUE constraint prevents two invoices from referring to the same order. A column in Categoria refers back to the same table to identify the parent category.</p><h3>Trying a change</h3><p>Edit an attribute in the conceptual model, click Generate/Update logical and review the proposed changes. Then press F8 to generate the new SQL. The example is configured for HSQLDB; you can also choose MySQL or MariaDB. PrezzoUnitario uses Money, while PesoKg is an approximate number.</p><h3>Rules to check</h3><p>Tables and keys cannot check every rule. You still need to check that orders have the required lines and that a category does not contain itself, directly or indirectly. If every customer must be either a private customer or a company, but not both, that also requires a check.</p>")));
  QDialogButtonBox buttons(QDialogButtonBox::Close);layout.addWidget(&buttons);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(760,570);dialog.exec();
 }
 void associationAttributesHelp(){
  QDialog dialog(this);dialog.setObjectName("associationAttributesHelp");dialog.setWindowTitle(t("Attributi dell’associazione","Relationship attributes"));QVBoxLayout layout(&dialog);
  auto text=new QLabel(t("La data e il prezzo di un acquisto descrivono una particolare vendita: una persona può acquistare lo stesso modello di automobile in date diverse e a prezzi diversi. Nei diagrammi E/R queste informazioni possono appartenere all’associazione. Qui puoi raccoglierle nell’entità Acquisto, collegata a Persona e ModelloAuto, come mostra il disegno.","The date and price of a purchase describe a particular sale: a person can buy the same car model on different dates and at different prices. In ER diagrams these details can belong to the relationship. Here you can place them in an Acquisto entity linked to Persona and ModelloAuto, as shown below."));text->setWordWrap(true);text->setStyleSheet(QString("padding:10px;background:%1;color:%2;").arg(learningColor(0).name(),Theme::textOn(learningColor(0)).name()));layout.addWidget(text);
  QGraphicsScene illustration;IllustrationView diagram(&illustration);diagram.setObjectName("associationIllustration");diagram.setRenderHint(QPainter::Antialiasing);diagram.setBackgroundBrush(theme.paper);diagram.setMinimumHeight(280);layout.addWidget(&diagram,1);
  auto label=[&](QString value,QRectF rect,bool box=false){if(box)illustration.addRect(rect,QPen(theme.line),theme.surface);auto item=illustration.addText(value,QFont("Segoe UI",10));item->setDefaultTextColor(theme.ink);item->setTextWidth(rect.width()-8);item->setPos(rect.topLeft()+QPointF(4,0));};
  auto line=[&](QPointF a,QPointF b,Qt::PenStyle style=Qt::SolidLine){illustration.addLine(QLineF(a,b),QPen(theme.line,1.5,style));};
  label(t("NOTAZIONE DEL LIBRO","TEXTBOOK NOTATION"),{0,0,740,30});
  label("Persona",{0,55,145,45},true);label("ModelloAuto",{580,55,160,45},true);line({145,77},{580,77});label("Acquistare",{285,40,140,35});line({360,77},{360,120},Qt::DashLine);label("DataAcquisto\nPrezzoAcquisto\nTarga",{265,120,200,80},true);
  label(t("NELL’APP: ENTITÀ ASSOCIATIVA","IN THE APP: ASSOCIATIVE ENTITY"),{0,225,740,35});
  auto savedPalette=qApp->palette();auto savedFont=qApp->font();auto savedStyle=qApp->styleSheet();Window example(true);qApp->setPalette(savedPalette);qApp->setFont(savedFont);qApp->setStyleSheet(savedStyle);setUiLanguage(en);example.en=en;example.mode=mode;example.preset=preset;example.custom=custom;example.theme=theme;example.model=purchaseExample();example.model.notes.clear();example.uml=true;example.showTypes=true;
  // A compact projection omits endpoint attributes; the same nodes and connectors
  // as the editable example render the essential association explanation.
  example.model.objects.erase(std::remove_if(example.model.objects.begin(),example.model.objects.end(),[](const Object &o){return o.kind=="attribute"&&o.owner!="acquisto";}),example.model.objects.end());
  for(auto &o:example.model.objects){if(o.kind=="attribute"&&o.dataType!="money")o.dataType.clear();if(o.id=="persona")o.uml={90,200};if(o.id=="acquisto")o.uml={430,200};if(o.id=="modello")o.uml={780,200};if(o.id=="effettua")o.uml={230,200};if(o.id=="riguarda")o.uml={640,200};}example.refresh();
  // Put cardinalities below the short connectors to avoid their labels colliding
  // with association names in this deliberately compact illustration.
  for(auto item:example.connectors)if(dynamic_cast<QGraphicsSimpleTextItem*>(item))item->moveBy(0,34);
  auto bounds=example.scene->itemsBoundingRect().adjusted(-12,-12,12,12);QPixmap rendered(1800,450);rendered.fill(theme.paper);{QPainter painter(&rendered);painter.setRenderHints(QPainter::Antialiasing|QPainter::TextAntialiasing);example.scene->render(&painter,QRectF(0,0,1800,450),bounds,Qt::KeepAspectRatio);}auto actual=illustration.addPixmap(rendered);actual->setScale(780./1800.);actual->setPos(0,270);actual->setData(1,"actualConceptualRenderer");
  label(t("Ogni acquisto: una persona e un modello. Ogni persona/modello: zero o più acquisti.","Each purchase: one person and one model. Each person/model: zero or more purchases."),{0,475,790,50});
  illustration.setSceneRect(illustration.itemsBoundingRect().adjusted(-8,-8,8,8));
  auto instructions=new QLabel(t("1. Crea Acquisto con identificatore e attributi.\n2. Sostituisci Acquistare con due associazioni 1:N.\n3. Genera il logico: Acquisto diventa una tabella con due FK.\nIdAcquisto distingue anche acquisti ripetuti della stessa persona e dello stesso modello.","1. Create Acquisto with an identifier and attributes.\n2. Replace Acquistare with two 1:N relationships.\n3. Generate the logical model: Acquisto becomes a table with two FKs.\nIdAcquisto also distinguishes repeated purchases by the same person of the same model."));instructions->setWordWrap(true);instructions->setStyleSheet(QString("padding:10px;background:%1;color:%2;").arg(learningColor(1).name(),Theme::textOn(learningColor(1)).name()));layout.addWidget(instructions);
  QDialogButtonBox buttons(QDialogButtonBox::Close);auto open=buttons.addButton(t("Apri esempio","Open example"),QDialogButtonBox::AcceptRole);open->setObjectName("openAssociationExample");layout.addWidget(&buttons);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(open,&QPushButton::clicked,&dialog,&QDialog::accept);dialog.resize(860,760);
  QTimer::singleShot(0,&dialog,[&]{diagram.fitInView(illustration.sceneRect(),Qt::KeepAspectRatio);});
  if(dialog.exec()==QDialog::Accepted)loadTeachingExample(false);
 }
